{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Two boundary bars indicate a 90-degree turn in the rasterized path;
    # interior marker advances toward the opposite boundary by its coordinate.
    marker = next(( (r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in (6,9)), None)
    if marker:
        r,c,v=marker
        # The isolated marker is propagated in the direction of the nearest colored border.
        if r < h//2:
            for rr in range(r): out[rr][c]=v
        else:
            for cc in range(c): out[r][cc]=v
    return out
