    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    from collections import Counter
    counts=Counter(x for row in grid for x in row); bg=counts.most_common(1)[0][0]
    colors=[x for x in counts if x!=bg]
    frame=max(colors,key=lambda x:counts[x])
    # Sparse marker color is propagated from each marker along its row/column
    # to the nearest frame; frame strokes themselves stay intact.
    for r in range(h):
        for c in range(w):
            x=grid[r][c]
            if x in (bg,frame): continue
            # if frame lies on row, extend toward the frame
            choices=[]
            for j in range(w):
                if grid[r][j]==frame: choices.append((abs(j-c),'h',j))
            for i in range(h):
                if grid[i][c]==frame: choices.append((abs(i-r),'v',i))
            if choices:
                _,axis,k=min(choices)
                if axis=='h':
                    for j in range(min(c,k)+1,max(c,k)): out[r][j]=x
                else:
                    for i in range(min(r,k)+1,max(r,k)): out[i][c]=x
    return out
